import React, { useState } from 'react';

function CurationSection() {
  const [activeIdx, setActiveIdx] = useState(0);

  // 💡 [데이터 구조] 큐레이션 영화 목록 데이터
  const curationList = [
    {
      id: 1,
      badge: "#필름소사이어티",
      ribbonText: "MEGABOX FILM SOCIETY",
      title: "싱 어 게인",
      quote: "“지금 당장, 노래 하나 써 봅시다”",
      description: "팝스타의 꿈은 접었지만 음악안에 놓지 못한 무명 축가 가수, 릭.\n한땐 잘나갔지만 지금은 나락 직전의 팝스타, 대니.\n우연히 만난 두 사람, 그들이 완성한 단 하나의 노래.\n하지만 그 곡은 오직 대니의 이름으로만 세상에 알려지는데-",
      // 👉 [주석] 좌측 메인 포스터 이미지 경로 (예: "/img/curation/main1.jpg")
      mainPoster: "",
      subItems: [
        { id: 101, title: "아가씨", image: "" },
        { id: 102, title: "퍼펙트 블루", image: "" },
        { id: 103, title: "[2026 NT Live] 인간 증오", image: "" },
        { id: 104, title: "청년 조용기: 산을 제주하…", image: "" }
      ]
    },
    {
      id: 2,
      badge: "#클래식소사이어티",
      ribbonText: "MEGABOX CLASSIC SOCIETY",
      title: "오페라의 유령",
      quote: "“거부할 수 없는 매혹의 이야기”",
      description: "오페라 하우스의 지하에 숨어 사는 천재 음악가와\n순수한 프리마돈나를 향한 딜레마와 거부할 수 없는 매혹의 이야기.",
      mainPoster: "",
      subItems: [
        { id: 201, title: "작은 아씨들", image: "" },
        { id: 202, title: "라 트라비아타", image: "public/img/00/02.jpg" },
        { id: 203, title: "백조의 호수", image: "" },
        { id: 204, title: "지젤", image: "" }
      ]
    }
  ];

  const currentItem = curationList[activeIdx];

  return (
    <section className="w-full bg-[#351b63] pt-16 pb-20 flex flex-col items-center relative overflow-hidden text-white">
      
      <div className="w-full max-w-6xl px-6">
        
        {/* 상단 타이틀 및 '큐레이션 더보기 +' */}
        <div className="flex justify-between items-center mb-10">
          <h2 className="text-2xl font-black tracking-tight text-white">큐레이션</h2>
          <button className="text-xs font-bold text-purple-300 hover:text-white transition">
            큐레이션 더보기 +
          </button>
        </div>

        {/* 큐레이션 메인 영역 (카드 형태 없이 보라색 배경에 자연스럽게 어우러짐) */}
        <div className="flex flex-col lg:flex-row gap-12 items-start justify-between">
          
          {/* [좌측] 메인 포스터 및 상세정보/예매 버튼 */}
          <div className="w-full lg:w-4/12 flex flex-col items-center relative">
            
            {/* 💡 [주석: 좌측 메인 영화 포스터 이미지 공간] */}
            <div className="relative w-full h-[450px] rounded-2xl overflow-hidden shadow-2xl bg-zinc-800 flex items-center justify-center mb-4 border border-zinc-700">
              
              {/* 좌측 상단 붉은색 리본 뱃지 (메가박스 필름소사이어티 스타일) */}
              <div className="absolute top-0 left-4 bg-[#e5383b] text-white text-[9px] font-black px-2.5 py-3 tracking-tighter shadow-md rounded-b flex flex-col items-center z-10">
                <span className="text-[7px] leading-none mb-0.5">MEGABOX</span>
                <span className="text-[10px] leading-none">FILM</span>
                <span className="text-[10px] leading-none">SOCIETY</span>
                <div className="absolute -bottom-1.5 w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[6px] border-t-[#a52224]"></div>
              </div>

              {currentItem.mainPoster ? (
                <img src={currentItem.mainPoster} alt={currentItem.title} className="w-full h-full object-cover" />
              ) : (
                <div className="text-center p-4">
                  <span className="text-xs font-bold text-zinc-400 block mb-1">메인 포스터 이미지 공간</span>
                  <span className="text-[10px] text-zinc-500">({currentItem.title})</span>
                </div>
              )}
            </div>

            {/* 상세정보 / 예매 버튼 */}
            <div className="w-full grid grid-cols-2 gap-3">
              <button className="py-3.5 rounded-xl bg-[#22103f] text-white font-bold text-xs border border-purple-400/30 hover:bg-[#1a0c30] transition">
                상세정보
              </button>
              <button className="py-3.5 rounded-xl bg-[#00a086] text-white font-bold text-xs hover:bg-[#008771] transition shadow-lg">
                예매
              </button>
            </div>

          </div>

          {/* [우측] 정보 텍스트 및 서브 썸네일 리스트 */}
          <div className="w-full lg:w-7/12 flex flex-col justify-between space-y-6">
            
            {/* 상단 텍스트 정보 */}
            <div>
              <span className="text-sm font-bold text-purple-300 block mb-1">
                {currentItem.badge}
              </span>
              <h3 className="text-4xl font-black text-white tracking-tight mb-6">
                {currentItem.title}
              </h3>

              {/* 구분선 */}
              <div className="w-full h-[1px] bg-purple-500/30 mb-6"></div>

              <p className="text-sm font-bold text-purple-200 mb-4">
                {currentItem.quote}
              </p>

              <p className="text-xs text-purple-100/80 font-medium leading-relaxed whitespace-pre-line">
                {currentItem.description}
              </p>
            </div>

            {/* 하단 가로형 서브 썸네일 리스트 */}
            <div className="pt-8">
              <div className="grid grid-cols-4 gap-4">
                {currentItem.subItems.map((sub, idx) => (
                  <div key={sub.id} className="flex flex-col gap-2 cursor-pointer group">
                    
                    {/* 💡 [주석: 우측 서브 영화 썸네일 이미지 공간] */}
                    <div className="relative w-full h-40 rounded-xl bg-zinc-800 overflow-hidden shadow-xl border border-purple-500/20 flex items-center justify-center">
                      
                      {/* 서브 포스터 상단 작은 뱃지 포인트 */}
                      <div className="absolute top-0 left-2 bg-[#e5383b] text-white text-[8px] font-bold px-1.5 py-2 z-10 shadow">
                        F
                      </div>

                      {sub.image ? (
                        <img src={sub.image} alt={sub.title} className="w-full h-full object-cover group-hover:scale-105 transition duration-300" />
                      ) : (
                        <span className="text-[10px] text-zinc-500 text-center px-1">썸네일 이미지</span>
                      )}
                    </div>

                    <span className="text-xs font-bold text-white truncate text-center group-hover:text-purple-300">
                      {sub.title}
                    </span>

                  </div>
                ))}
              </div>
            </div>

          </div>

        </div>

      </div>

    </section>
  );
}

export default CurationSection;
